using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Tilemaps;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.U2D.Sprites;using Object=UnityEngine.Object;
public static class DemoGroundingSetup
{
 public const float TrapOffset=.59f,PlayerFoot=-.495f;
 const string Enc="Assets/Prefabs/Encounters/";
 public static void Run(){try{AlignPlayer();AlignTraps();JoinRoute();AssetDatabase.SaveAssets();File.WriteAllText("grounding-setup.txt","Player grounded animation feet: -0.495; trap root: floor + 0.59; painted route underside joins rebuilt.\n");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void AlignPlayer(){string path="Assets/Sprites/Characters/Red/Red.png";var i=(TextureImporter)AssetImporter.GetAtPath(path);bool readable=i.isReadable;i.isReadable=true;i.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var pixels=tex.GetPixels32();var factories=new SpriteDataProviderFactories();factories.Init();var provider=factories.GetSpriteEditorDataProviderFromObject(i);provider.InitSpriteEditorDataProvider();var frames=provider.GetSpriteRects();
 foreach(var f in frames){int index=int.Parse(f.name.Split('_').Last());if(index>=13&&index<=18)continue;int bottom=(int)f.rect.yMax;for(int y=(int)f.rect.y;y<f.rect.yMax;y++)for(int x=(int)f.rect.x;x<f.rect.xMax;x++)if(pixels[y*tex.width+x].a>128)bottom=Mathf.Min(bottom,y);f.alignment=SpriteAlignment.Custom;f.pivot=new Vector2(f.pivot.x,(bottom-f.rect.y-PlayerFoot*i.spritePixelsPerUnit)/f.rect.height);}
 provider.SetSpriteRects(frames);provider.Apply();i.isReadable=readable;i.SaveAndReimport();}
 static void AlignTraps(){foreach(string path in Directory.GetFiles(Enc,"*.prefab").Concat(Directory.GetFiles("Assets/Prefabs/PaintedChunks","*.prefab"))){var r=PrefabUtility.LoadPrefabContents(path);Physics2D.SyncTransforms();foreach(var t in r.GetComponentsInChildren<TrapDamage>(true)){var pos=t.transform.position;var hit=r.scene.GetPhysicsScene2D().Raycast((Vector2)pos+Vector2.up*2,Vector2.down,5,1<<8);if(hit.collider!=null)t.transform.position=new Vector3(pos.x,hit.point.y+TrapOffset,pos.z);}foreach(var s in r.GetComponentsInChildren<ChunkTrapSpawner>(true))s.yOffset=TrapOffset;PrefabUtility.SaveAsPrefabAsset(r,path);PrefabUtility.UnloadPrefabContents(r);}}
 static float Bottom(GameObject root,float x){float min=float.PositiveInfinity;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){if(f.name!="Painted surface")continue;var vs=f.sharedMesh.vertices;var ts=f.sharedMesh.triangles;for(int n=0;n<ts.Length;n+=3)for(int j=0;j<3;j++){var a=root.transform.InverseTransformPoint(f.transform.TransformPoint(vs[ts[n+j]]));var b=root.transform.InverseTransformPoint(f.transform.TransformPoint(vs[ts[n+(j+1)%3]]));if(x<Mathf.Min(a.x,b.x)-.001f||x>Mathf.Max(a.x,b.x)+.001f)continue;if(Mathf.Abs(a.x-b.x)<.001f){if(Mathf.Abs(x-a.x)<.001f)min=Mathf.Min(min,a.y,b.y);}else min=Mathf.Min(min,Mathf.Lerp(a.y,b.y,(x-a.x)/(b.x-a.x)));}}return min;}
 static void JoinRoute(){EditorSceneManager.OpenScene("Assets/Scenes/PaintedDimension.unity");var gen=Object.FindAnyObjectByType<LevelGenerator>();var paths=gen.startChunks.Take(1).Concat(gen.encounterChunks).Concat(gen.endChunks.Take(1)).Select(AssetDatabase.GetAssetPath).ToArray();
 // Remove our own prior additions only, so the operation is repeatable.
 foreach(var path in paths){var r=PrefabUtility.LoadPrefabContents(path);foreach(var t in r.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Underside join")).ToArray())Object.DestroyImmediate(t.gameObject);PrefabUtility.SaveAsPrefabAsset(r,path);PrefabUtility.UnloadPrefabContents(r);}
 for(int n=0;n<paths.Length-1;n++){var left=PrefabUtility.LoadPrefabContents(paths[n]);var right=PrefabUtility.LoadPrefabContents(paths[n+1]);var end=left.transform.Find("EndPosition").localPosition;float a=Bottom(left,end.x),b=Bottom(right,0)+end.y;if(float.IsInfinity(a)||float.IsInfinity(b))throw new Exception("Missing boundary "+paths[n]);if(Mathf.Abs(a-b)>.01f){if(a>b)Skirt(left,end.x,-1,b,"Right");else Skirt(right,0,1,a-end.y,"Left");}PrefabUtility.SaveAsPrefabAsset(left,paths[n]);PrefabUtility.SaveAsPrefabAsset(right,paths[n+1]);PrefabUtility.UnloadPrefabContents(left);PrefabUtility.UnloadPrefabContents(right);}}
 static void Skirt(GameObject root,float seam,float direction,float target,string side){float width=4;float inner=Bottom(root,seam+direction*width);if(float.IsInfinity(inner))return;var v=new List<Vector3>();var uv=new List<Vector2>();var colors=new List<Color>();var tri=new List<int>();for(int k=0;k<16;k++){float x0=seam+direction*width*k/16,x1=seam+direction*width*(k+1)/16;float y0=Bottom(root,x0),y1=Bottom(root,x1);float b0=Mathf.Min(y0,Mathf.Lerp(target,inner,k/16f)),b1=Mathf.Min(y1,Mathf.Lerp(target,inner,(k+1)/16f));int start=v.Count;foreach(var p in new[]{new Vector3(x0,y0+.005f,.01f),new Vector3(x1,y1+.005f,.01f),new Vector3(x1,b1,.01f),new Vector3(x0,b0,.01f)}){v.Add(p);uv.Add((Vector2)p/4);colors.Add(new Color(1,1,1,0));}tri.AddRange(new[]{start,start+1,start+2,start,start+2,start+3});}
 var mesh=new Mesh{name=root.name+" underside "+side};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetColors(colors);mesh.SetTriangles(tri,0);mesh.RecalculateBounds();string path="Assets/Art/Painted/Meshes/"+root.name+"_Join"+side+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(mesh,path);else EditorUtility.CopySerialized(mesh,old);var go=new GameObject("Underside join "+side);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);go.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Painted/ColdCavernStone.mat");}
}
